import re, random

PATH = '/home/lane/MythosMini/slm_alliance.html'
src = open(PATH).read()
random.seed(42)

def jitter(d, amt):
    def j(m):
        return format(float(m.group(0)) + random.uniform(-amt, amt), '.1f')
    return re.sub(r'-?\d+(?:\.\d+)?', j, d)

def rebuild(start_marker, end_marker, base, amt):
    """replace all <path d> in region with base + 3 jittered frames (4 total)"""
    global src
    i = src.index(start_marker)
    e = src.index(end_marker, i)
    region = src[i:e]
    fs = [jitter(base, amt) for _ in range(4)]
    # strip existing paths, rebuild with 4
    stroke = re.search(r'(fill="none" stroke="[^"]+" stroke-width="[^"]+" stroke-linecap="round")', region).group(1)
    new_paths = '\n'.join('<path d="%s" %s/>' % (f, stroke) for f in fs)
    region = re.sub(r'(<path d="[^"]*"[^>]*/>\s*)+', new_paths + '\n', region, count=1)
    src = src[:i] + region + src[e:]

under = 'M4 11 Q 22 6 40 11 T 76 11 T 112 11 T 148 10 T 184 11 T 220 10 T 256 11 T 295 10'
rebuild('Smaller is smarter.<svg', '</svg></span>', under, 2.2)

circ = 'M100 5 C 158 3 195 14 195 35 C 195 57 152 67 99 66 C 45 65 5 55 5 34 C 5 13 46 7 100 5 Z'
rebuild('&lt;100M<svg', '</svg></span></div>', circ, 2.8)

div_base = 'M2 14 Q 50 9 100 14 T 200 13 T 300 14 T 400 13 T 500 14 T 600 13 T 700 14 T 800 13 T 900 14 T 1000 13 T 1100 14 T 1198 13'
for _ in range(2):
    idx = src.index('<svg class="divider-squiggle')
    end = src.index('</svg>', idx)
    region = src[idx:end]
    fs = [jitter(div_base, 2.4) for _ in range(4)]
    stroke = 'fill="none" stroke="#d97757" stroke-width="2.5" stroke-linecap="round"'
    new_paths = '\n'.join('    <path d="%s" %s/>' % (f, stroke) for f in fs)
    region = re.sub(r'(\s*<path d="[^"]*"[^>]*/>)+', '\n' + new_paths, region, count=1)
    region = region.replace('divider-squiggle', 'dividerSquiggle', 1)
    src = src[:idx] + region + src[end:]
src = src.replace('dividerSquiggle', 'divider-squiggle')

acc = 'M2 8 Q 16 5 30 8 T 58 7 T 86 8 T 118 7'
rebuild('style="width:120px;height:14px;margin-top:1.4rem;overflow:visible;" viewBox="0 0 120 14"', '</svg>', acc, 1.8)

# 4-frame flipbook: each frame visible 25% of an 0.8s cycle (5 redraws/sec)
src = src.replace('''@keyframes boil {
    0%, 32.9% { opacity: 1; }
    33%, 100% { opacity: 0; }
}''', '''@keyframes boil {
    0%, 24.9% { opacity: 1; }
    25%, 100% { opacity: 0; }
}''')
src = src.replace('''.squiggle path, .squiggle ellipse {
    opacity: 0;
    animation: boil 0.9s steps(1) infinite;
}

.squiggle path:nth-of-type(2), .squiggle ellipse:nth-of-type(2) { animation-delay: 0.3s; }
.squiggle path:nth-of-type(3), .squiggle ellipse:nth-of-type(3) { animation-delay: 0.6s; }''', '''.squiggle path {
    opacity: 0;
    animation: boil 0.8s steps(1) infinite;
}

.squiggle path:nth-of-type(2) { animation-delay: 0.2s; }
.squiggle path:nth-of-type(3) { animation-delay: 0.4s; }
.squiggle path:nth-of-type(4) { animation-delay: 0.6s; }''')

open(PATH, 'w').write(src)
print('OK')
